changeSet.sql:
ALTER TABLE finances.stock_lots ADD COLUMN purchase_amount NUMERIC NULL;
ALTER TABLE finances.crypto_lots ADD COLUMN purchase_amount NUMERIC NULL;
ALTER TABLE finances.fund_contributions ADD COLUMN purchase_amount NUMERIC NULL;

UPDATE finances.stock_lots SET purchase_amount = quantity * price;
UPDATE finances.crypto_lots SET purchase_amount = quantity * price;
UPDATE finances.fund_contributions SET purchase_amount = amount;

rollback.sql:
ALTER TABLE finances.fund_contributions DROP COLUMN purchase_amount;
ALTER TABLE finances.crypto_lots DROP COLUMN purchase_amount;
ALTER TABLE finances.stock_lots DROP COLUMN purchase_amount;

changeSet.sql:
CREATE FUNCTION finances.record_lot_purchase_amount() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.purchase_amount IS NULL AND NEW.origin <> 'MOVE' THEN
        NEW.purchase_amount := NEW.quantity * NEW.price;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION finances.record_contribution_purchase_amount() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.purchase_amount IS NULL AND NEW.origin <> 'MOVE' THEN
        NEW.purchase_amount := NEW.amount;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER stock_lots_purchase_amount BEFORE INSERT ON finances.stock_lots
    FOR EACH ROW EXECUTE FUNCTION finances.record_lot_purchase_amount();
CREATE TRIGGER crypto_lots_purchase_amount BEFORE INSERT ON finances.crypto_lots
    FOR EACH ROW EXECUTE FUNCTION finances.record_lot_purchase_amount();
CREATE TRIGGER fund_contributions_purchase_amount BEFORE INSERT ON finances.fund_contributions
    FOR EACH ROW EXECUTE FUNCTION finances.record_contribution_purchase_amount();

rollback.sql:
DROP TRIGGER fund_contributions_purchase_amount ON finances.fund_contributions;
DROP TRIGGER crypto_lots_purchase_amount ON finances.crypto_lots;
DROP TRIGGER stock_lots_purchase_amount ON finances.stock_lots;
DROP FUNCTION finances.record_contribution_purchase_amount();
DROP FUNCTION finances.record_lot_purchase_amount();
